using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CasinoProbe{static CasinoProbe(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CasinoProbe.request"))return;File.Delete("CasinoProbe.request");try{var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var fs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>(true)).Where(f=>f.name=="Casino").ToArray();var rows=fs.Select(f=>f.name+" "+f.GetComponent<Renderer>().bounds+" transform="+f.transform.localToWorldMatrix).ToList();foreach(var f in fs){var data=typeof(FinalPNGCityDetails).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{f.sharedMesh});var ps=(Vector3[])data.GetType().GetField("p").GetValue(data);var w=ps.Select(f.transform.TransformPoint).ToArray();rows.AddRange(w.Where(v=>v.x>-391).GroupBy(v=>Mathf.Round(v.y*10)/10).Select(g=>"front level "+g.Key+" z="+g.Min(v=>v.z)+".."+g.Max(v=>v.z)+" x="+g.Max(v=>v.x)));}rows.Add("view="+SceneView.lastActiveSceneView.camera.transform.position+" pivot="+SceneView.lastActiveSceneView.pivot);var flags=BindingFlags.Static|BindingFlags.NonPublic;foreach(var f in fs){var b=f.GetComponent<Renderer>().bounds;typeof(FinalPNGCityDetails).GetMethod("Capture",flags).Invoke(null,new object[]{s,b.center+new Vector3(0,0,95),b.center,"Casino-Before-Front"});typeof(FinalPNGCityDetails).GetMethod("Capture",flags).Invoke(null,new object[]{s,b.center+new Vector3(95,0,0),b.center,"Casino-Before-Side"});}File.WriteAllLines("FinalEnvironmentRoadReview/CasinoProbe.txt",rows);}catch(Exception e){File.WriteAllText("FinalEnvironmentRoadReview/CasinoProbe.txt",e.ToString());}}}

